from html.parser import HTMLParser
from views import render_comment

class Extract(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack, self.texts = [], []
    def handle_starttag(self, tag, attrs):
        self.stack.append((tag, dict(attrs)))
    def handle_data(self, data):
        self.texts.append(data)

for c in ['2 < 3', 'AT&T & \"Sons\"', \"it's <b>not</b> bold\", 'a > b & c < d']:
    p = Extract(); p.feed(render_comment(c))
    assert p.stack == [('div', {'class': 'comment'})], p.stack
    assert ''.join(p.texts) == c, (p.texts, c)
print('round-trip OK: text content preserved, single div.comment, no child elements')
